    private JSONObject config(JSONObject value)throws Exception{JSONObject out=new JSONObject();String theme=value.optString("theme","blue");if(!Arrays.asList("blue","night","emerald","amber","violet","ahly","zamalek","barcelona","madrid","egypt","basketball","baseball","montreal","toronto","argentina","portugal","ismaily","king-salman","crown-prince","nassr","hilal","ittihad","ahli-saudi","inter-miami","saudi-national","egypt-national","blue-cinema","gta6").contains(theme))throw new IOException("Unknown theme");out.put("theme",theme);for(String key:new String[]{"fontSizeAr","fontSizeEn"}){String font=value.optString(key,"normal");out.put(key,Arrays.asList("small","normal","large").contains(font)?font:"normal");}out.put("cardWidth",Math.max(220,Math.min(380,value.optInt("cardWidth",300))));out.put("customTitle",value.optString("customTitle","").substring(0,Math.min(48,value.optString("customTitle","").length())));String subtitle=value.optString("customSubtitle","");out.put("customSubtitle",subtitle.substring(0,Math.min(64,subtitle.length())));String accent=value.optString("accent","");out.put("accent",accent.matches("#[0-9a-fA-F]{6}")?accent:"");for(String color:new String[]{"backgroundStart","backgroundEnd","cardColor","textColor"}){String hex=value.optString(color,"");out.put(color,hex.matches("#[0-9a-fA-F]{6}")?hex:"");}for(String size:new String[]{"heroTitleSize","heroSubtitleSize","heroArtSize","heroLogoSize"})out.put(size,Math.max(70,Math.min(size.equals("heroTitleSize")||size.equals("heroSubtitleSize")?120:125,value.optInt(size,100))));out.put("showClock",value.optBoolean("showClock",true));out.put("showWeather",value.optBoolean("showWeather",true));out.put("showPrayer",value.optBoolean("showPrayer",true));for(String image:new String[]{"logoImage","artImage"}){String data=value.optString(image,"");out.put(image,data.length()<240000&&data.matches("data:image/(png|jpeg);base64,[A-Za-z0-9+/=]+")?data:"");}JSONArray slides=value.optJSONArray("backgroundImages"),clean=new JSONArray();if(slides!=null)for(int i=0;i<Math.min(5,slides.length());i++){String data=slides.optString(i,"");if(data.length()<=90000&&data.matches("data:image/(png|jpeg);base64,[A-Za-z0-9+/=]+"))clean.put(data);}for(String pos:new String[]{"artOffsetX","artOffsetY","textOffsetX","textOffsetY","logoOffsetX","logoOffsetY"})out.put(pos,Math.max(-25,Math.min(25,value.optInt(pos,0))));for(String tint:new String[]{"iconTint","highlightColor"}){String hex=value.optString(tint,"");out.put(tint,hex.matches("#[0-9a-fA-F]{6}")?hex:"");}out.put("glassOpacity",Math.max(10,Math.min(80,value.optInt("glassOpacity",18))));out.put("backgroundImages",clean);out.put("slideshowEnabled",value.optBoolean("slideshowEnabled",false));out.put("slideshowSeconds",Math.max(8,Math.min(60,value.optInt("slideshowSeconds",15))));return out;}
    private SdbClient connect()throws Exception{if(!brand.equals("samsung"))throw new IOException("اكتشاف LG متاح، لكن التثبيت والتخصيص على webOS غير متاحين في النسخة دي بعد.");if(!Network.local(ip))throw new IOException("اختار تلفزيون من صفحة الاتصال الأول.");return new SdbClient(ip);}
    private Inspector inspectorAt(int port)throws Exception{
        JSONArray targets=new JSONArray(Network.get("http://"+ip+":"+port+"/json",1800));
        for(int j=0;j<targets.length();j++){
            String url=targets.getJSONObject(j).optString("webSocketDebuggerUrl");if(url.isEmpty())continue;
            URI uri=new URI(url);if(!ip.equals(uri.getHost())||uri.getPort()!=port)throw new IOException("Invalid inspector target");
            return new Inspector(url);
        }
        throw new IOException("Morph TV inspector is not ready");
    }
    private int debugPort(SdbClient s)throws Exception{
        Pattern pattern=Pattern.compile("port[:\\s]+(\\d+)");String reply;
        s.timeout(7000);
        try{reply=s.shellUntil("0 debug "+APP,pattern);}
        catch(java.net.SocketTimeoutException e){throw new IOException("اقفل Morph TV من الشاشة بزر رجوع، وبعدها اضغط تطبيق التعديلات من الموبايل. اتصال التخصيص لم يفتح.",e);}
        finally{s.timeout(20000);}
        Matcher matcher=pattern.matcher(reply);if(!matcher.find())throw new IOException("اقفل Morph TV من الشاشة بزر رجوع ثم جرّب تطبيق التعديلات من الموبايل.");
        int port=Integer.parseInt(matcher.group(1));if(port<1||port>65535)throw new IOException("Invalid inspector port");
        prefs.edit().putInt("samsungDebugPort:"+ip,port).apply();return port;
    }
    private Inspector inspector()throws Exception{return inspector(true);}
    private Inspector inspector(boolean allowStart)throws Exception{
        status("فتح اتصال التخصيص بوضع المطوّر…");
        int cached=prefs.getInt("samsungDebugPort:"+ip,0);
        if(cached>0){try{return inspectorAt(cached);}catch(Exception ignored){prefs.edit().remove("samsungDebugPort:"+ip).apply();}}
        if(!allowStart)throw new IOException("Open Morph TV on the TV to reconnect. Connection checks do not launch it.");
        int port;try(SdbClient s=connect()){port=debugPort(s);}Exception last=null;
        for(int i=0;i<6;i++){try{return inspectorAt(port);}catch(Exception e){last=e;}Thread.sleep(300);}
        throw new IOException("تعذّر فتح واجهة Morph TV للتخصيص. اقفلها بزر رجوع ثم جرّب من الموبايل.",last);
    }
