         if(brand.equals("android")){JSONObject info=AndroidTv.request(ip,"/info",null,null);if(!info.optBoolean("themePacks"))return new JSONObject().put("legacyBundled",true);String key=AndroidTv.token(this,ip);JSONObject command=new JSONObject().put("id",id).put("action","download");long until=System.currentTimeMillis()+180000;JSONObject state=AndroidTv.request(ip,"/theme-packs",command,key);while(!state.optBoolean("installed")){if(state.optString("state").equals("error"))throw new IOException(state.optString("error").equals("plus_required")?"فعّل Morph TV Plus على التلفزيون نفسه من Settings ثم General settings ثم Morph TV Plus. تفعيل الموبايل وحده لا يفعّل التلفزيون.":"TV theme pack download failed. Check TV internet and storage, then retry.");if(System.currentTimeMillis()>until)throw new IOException("TV theme pack download timed out. Keep Morph TV open and retry.");status("TV theme pack: "+state.optInt("percent")+"%");Thread.sleep(500);state=AndroidTv.request(ip,"/theme-packs",new JSONObject().put("id",id),key);}return state;}
