        if(action.equals("familyProfiles")){String operation=payload.optString("operation","list");if(!Arrays.asList("list","create","select").contains(operation))throw new IOException("Invalid profile operation");if(brand.equals("android"))return AndroidTv.request(ip,"/profiles",payload,AndroidTv.token(this,ip));if(brand.equals("samsung")){try(Inspector tv=inspector(!operation.equals("list"))){Object reply=tv.evaluate("JSON.stringify(window.ClearTV.familyAction("+JSONObject.quote(operation)+","+payload.toString()+"))");return new JSONObject(String.valueOf(reply));}}throw new IOException("Family profiles require Android TV or Samsung");}
