        @JavascriptInterface public void setAppearance(String mode){String selected="dark".equals(mode)?"dark":"light";prefs.edit().putString("appearance",selected).apply();runOnUiThread(()->systemAppearance(selected));}
        @JavascriptInterface public String settingsJson(){return "{\"language\":\""+prefs.getString("language","ar")+"\"}";}
        @JavascriptInterface public void setLanguage(String language){if(Arrays.asList("ar","en","fr","zh","ja").contains(language))prefs.edit().putString("language",language).apply();}
        @JavascriptInterface public void request(String id,String action,String payload){if(action.equals("openCastSettings")){runOnUiThread(()->{try{result(id,true,new JSONObject().put("opened",CastSettings.open(MainActivity.this)));}catch(Exception e){result(id,false,"Could not open Cast settings.");}});return;}if(action.equals("pickImage")){runOnUiThread(()->{try{if(imageRequest!=null)throw new IOException("اختار الصورة الحالية الأول.");String role=new JSONObject(payload).optString("role");if(!Arrays.asList("logo","art").contains(role))throw new IOException("Invalid image role");imageRequest=id;imageRole=role;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(pick,31);}catch(Exception e){imageRequest=null;result(id,false,e.getMessage());}});return;}worker.execute(()->{try{result(id,true,run(action,new JSONObject(payload)));}catch(Exception e){result(id,false,e.getMessage()==null?"تعذّر تنفيذ الطلب.":e.getMessage());}});}
        @JavascriptInterface public void saveDraft(String json){try{prefs.edit().putString("draft",config(new JSONObject(json)).toString()).apply();}catch(Exception ignored){}}
