    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==31&&imageRequest!=null){final String id=imageRequest,role=imageRole;imageRequest=null;if(resultCode!=RESULT_OK||data==null){result(id,false,"تم إلغاء اختيار الصورة.");return;}final Uri uri=data.getData();worker.execute(()->{try{result(id,true,new JSONObject().put("role",role).put("data",ImageAsset.read(this,uri,role)));}catch(Exception e){result(id,false,"تعذّر قراءة الصورة. جرّب PNG أو JPEG أصغر.");}});}}
    @Override protected void onDestroy(){if(downloadServer!=null)downloadServer.close();if(samsungRemote!=null)samsungRemote.close();super.onDestroy();}
